  async fetch(request, env) {
    // Example Cloudflare Durable Object usage (simplified)
    const id = env.MY_DO_NAMESPACE.idFromName('room:123')
    const obj = env.MY_DO_NAMESPACE.get(id)
    const resp = await obj.fetch(request)
    return resp
  }
