// Durable Object (class) handler
export class Room {
  constructor(state, env) {
    this.state = state
    this.env = env
    this.messages = []
  }

  async fetch(req) {
    if (req.method === 'POST') {
      const msg = await req.text()
      // All writes serialized by this instance
      this.messages.push(msg)
      await this.state.storage.put('messages', this.messages)
      return new Response('ok', { status: 200 })
    }
    // GET returns current messages
    return new Response(JSON.stringify(this.messages), { status: 200 })
  }
}
